// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import { FullMath } from "@UniswapV4Core/libraries/FullMath.sol";
import { TickMath } from "@UniswapV4Core/libraries/TickMath.sol";


/**
 * @title PriceLib
 * @notice Human-readable price math for the SafeSwap LP NFT card. Converts a Uniswap V4 `sqrtPriceX96` (and the
 *         position's tick bounds) into a token1-per-token0 price, decimal-adjusted for both tokens and scaled to
 *         18 fixed-point decimals so `StringHelperLib.format_price` can render it.
 *
 *         price(token1 per token0) = (sqrtPriceX96 / 2^96)^2 * 10^decimals0 / 10^decimals1
 *
 *         Returned value is that price multiplied by 1e18.
 */
library PriceLib {

    uint256 internal constant PRICE_SCALE   =  1e18;                          // output fixed-point scale
    uint256 internal constant Q96           =  0x1000000000000000000000000;   // 2**96
    uint8   internal constant MAX_DECIMALS  =  36;                            // clamp to keep the mulDiv result in range

    /**
     * @notice Price of one whole token0 expressed in token1, scaled by 1e18 and adjusted for token decimals.
     * @dev Two-step FullMath keeps the 512-bit intermediate in range: `ratio = sqrtP^2 / 2^96`, then
     *      `price*1e18 = ratio * 10^(decimals0+18) / (2^96 * 10^decimals1)`.
     */
    function price1_per_0_scaled( uint160 sqrt_price_x96, uint8 decimals0, uint8 decimals1 )
    internal pure returns ( uint256 )
    {
        if(  sqrt_price_x96 == 0  )  return 0;

        uint256 d0  =  decimals0 > MAX_DECIMALS  ?  MAX_DECIMALS  :  decimals0;
        uint256 d1  =  decimals1 > MAX_DECIMALS  ?  MAX_DECIMALS  :  decimals1;

        uint256 ratio        =  FullMath.mulDiv( sqrt_price_x96, sqrt_price_x96, Q96 );   // sqrtP^2 / 2^96
        uint256 numerator    =  10 ** ( d0 + 18 );
        uint256 denominator  =  Q96 * ( 10 ** d1 );

        return FullMath.mulDiv( ratio, numerator, denominator );
    }

    /**
     * @notice token1-per-token0 price (scaled by 1e18) at a tick boundary — used for the range bar's low/high ends.
     */
    function price_at_tick_scaled( int24 tick, uint8 decimals0, uint8 decimals1 )
    internal pure returns ( uint256 )
    {
        return price1_per_0_scaled( TickMath.getSqrtPriceAtTick( tick ), decimals0, decimals1 );
    }

    /**
     * @notice Price of one whole token1 expressed in token0, scaled by 1e18 and adjusted for token decimals — the inverse
     *         orientation of `price1_per_0_scaled`. Used by the signed Create receipt, which quotes Range / Price as
     *         token0-per-token1 (e.g. "3,002.5 USDC/WETH" where USDC is token0 and WETH is token1).
     * @dev Computed by inverting the token1-per-token0 price (`1e36 / price1_per_0`). The inversion's rounding is far below
     *      display precision and is acceptable here: Create's economic safety rests on the committed deposit / minimum
     *      amounts, not on bit-exact price (see DYNAMIC_FEE_REBATE_PLAN.md / SIGNING_UX_REFERENCE_2.md).
     */
    function price0_per_1_scaled( uint160 sqrt_price_x96, uint8 decimals0, uint8 decimals1 )
    internal pure returns ( uint256 )
    {
        uint256 price1_per_0  =  price1_per_0_scaled( sqrt_price_x96, decimals0, decimals1 );
        if(  price1_per_0 == 0  )  return 0;

        return FullMath.mulDiv( PRICE_SCALE, PRICE_SCALE, price1_per_0 );
    }

    /**
     * @notice Where the current price sits within [low, high], as a 0..width fill for the range-bar marker.
     *         Clamps to the ends when the price is out of range (price below low → 0, above high → width).
     * @dev Linear in PRICE, not tick — the card shows a price axis, so the marker spacing should track price
     *      (callers pass the scaled prices, not ticks). A tick-linear scale would misplace the thumb vs the labels.
     */
    function fill_width( uint256 current, uint256 low, uint256 high, uint256 width )
    internal pure returns ( uint256 )
    {
        if(  high <= low  ||  current <= low  )  return 0;
        if(  current >= high  )                  return width;

        return FullMath.mulDiv( current - low, width, high - low );
    }
}

contracts/Common/SafeSwapCommon.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "@BondRouteProtected/BondRouteProtected.sol";
import "@SafeSwapCommon/Definitions.sol";
import "@SafeSwapCommon/Types.sol";
import { IPoolManager } from "@UniswapV4Core/interfaces/IPoolManager.sol";
import { IHooks } from "@UniswapV4Core/interfaces/IHooks.sol";
import { PoolKey } from "@UniswapV4Core/types/PoolKey.sol";
import { Currency } from "@UniswapV4Core/types/Currency.sol";
import { FullMath } from "@UniswapV4Core/libraries/FullMath.sol";
import { FixedPoint96 } from "@UniswapV4Core/libraries/FixedPoint96.sol";
import { LPFeeLibrary } from "@UniswapV4Core/libraries/LPFeeLibrary.sol";


// ━━━━  ERRORS  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

error SlippageExceeded( uint256 amount_received, uint256 minimum_required );
error MaximumInputExceeded( uint256 required_input, uint256 maximum_required );
error OneSidedDepositMismatch( address expected_token, uint256 minimum_required );
error RepricingFeeExceedsV4Limit( uint256 total_fee_pips, uint256 maximum_fee_pips );

// The swap funding the bond carries must match the input the user signed in the receipt (`Pay`). The signed input is the
// display source of truth; a relayer cannot fund a different token or amount than the one the user saw and signed.
error SignedSwapInputMismatch( address signed_token, uint256 signed_amount, address funded_token, uint256 funded_amount );


/**
 * @title SafeSwapCommon
 * @notice Shared utilities for SafeSwap action libraries.
 * @dev Constants, pool key building, stake calculation, protocol fee math, repricing-fee math, and settlement logic.
 */
library SafeSwapCommon {
    using FundingsLib for BondContext;

    // EIP-712 type hashes shared across action libs.
    bytes32 constant POOL_INFO_TYPEHASH     =  keccak256( "PoolInfo(uint16 base_fee_bps,uint8 rebate_percent,int24 tick_spacing)" );
    bytes32 constant TOKEN_AMOUNT_TYPEHASH  =  keccak256( "TokenAmount(address token,uint256 amount)" );


    // ━━━━  EIP-712 HELPERS  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    // EIP-712 encodes each atomic member into a full 32-byte word: uint8 zero-padded, int24 sign-extended. `abi.encode`
    // produces exactly that layout, so we hash it directly rather than hand-rolling assembly for this off-chain signing path.
    function hash_pool_info( PoolInfo memory pool_info ) internal pure returns ( bytes32 result )
    {
        result  =  keccak256( abi.encode(
            POOL_INFO_TYPEHASH,
            pool_info.base_fee_bps,
            pool_info.rebate_percent,
            pool_info.tick_spacing
        ));
    }

    function hash_token_amount( TokenAmount memory token_amount ) internal pure returns ( bytes32 result )
    {
        bytes32 typehash  =  TOKEN_AMOUNT_TYPEHASH;

        assembly ("memory-safe")
        {
            let saved_free_memory_pointer  :=  mload( 0x40 )

            // Lay out  typehash || token || amount  across the 96 bytes spanning the scratch
            // space (0x00-0x3f) and the free-memory-pointer slot (0x40-0x5f). This leaves no
            // garbage above the free memory pointer.
            // The token field is a memory-stored address, already right-aligned in its 32-byte slot.
            mstore( 0x00, typehash )
            mstore( 0x20, mload( token_amount ) )                  // token
            mstore( 0x40, mload( add( token_amount, 0x20 ) ) )     // amount

            result  :=  keccak256( 0x00, 0x60 )

            mstore( 0x40, saved_free_memory_pointer )    // *SECURITY*  -  Restore the free memory pointer we just clobbered.
        }
    }


    // ━━━━  POOL CONFIG HELPERS  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    /**
     * @notice Convert a base LP fee in basis points into Uniswap V4 fee units (pips).
     * @dev 100 v4 pips = 1 bps. E.g. 30 bps (0.3%) → 3000 pips.
     */
    function compute_base_fee_pips( uint16 base_fee_bps ) internal pure returns ( uint24 )
    {
        return uint24(base_fee_bps) * uint24(PIPS_PER_BPS);
    }


    // ━━━━  TOKEN AMOUNT HELPERS  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    /**
     * @notice Sort a two-element TokenAmount pair into Uniswap V4 pool currency order.
     * @dev Reverts with `TOKENS_MUST_BE_DIFFERENT` if both entries reference the same token.
     */
    function sort_token_amount_pair( TokenAmount memory pair_a, TokenAmount memory pair_b )
    internal pure returns ( IERC20 token0, uint256 amount0, IERC20 token1, uint256 amount1 )
    {
        if(  address(pair_a.token) == address(pair_b.token)  )  revert( TOKENS_MUST_BE_DIFFERENT );

        ( token0, amount0, token1, amount1 )  =  address(pair_a.token) < address(pair_b.token)
            ? ( pair_a.token, pair_a.amount, pair_b.token, pair_b.amount )
            : ( pair_b.token, pair_b.amount, pair_a.token, pair_a.amount );
    }


    // ━━━━  POOL KEY BUILDER  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    function build_pool_key( IERC20 token_in, IERC20 token_out, uint24 fee, int24 tick_spacing, address hook_address )
    internal pure returns ( PoolKey memory )
    {
        ( Currency currency0, Currency currency1 )  =  address(token_in) < address(token_out)
            ? ( Currency.wrap(address(token_in)), Currency.wrap(address(token_out)) )
            : ( Currency.wrap(address(token_out)), Currency.wrap(address(token_in)) );

        return PoolKey({
            currency0: currency0,
            currency1: currency1,
            fee: fee,
            tickSpacing: tick_spacing,
            hooks: IHooks(hook_address)
        });
    }


    // ━━━━  STAKE CALCULATION  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    function calculate_swap_stake( TokenAmount memory funding ) internal pure returns ( TokenAmount memory )
    {
        uint256 stake_amount  =  funding.amount * SWAP_STAKE_PERCENTAGE / 100;

        // *SECURITY*  -  Bump dust to 1 wei. For 0-decimal / low-decimal tokens where 1 wei = 1 unit = real value
        //                (gaming ERC20s, fractional RWAs), this turns a free speculative bond into a meaningful stake.
        if(  stake_amount == 0  )  stake_amount  =  1;

        return TokenAmount({ token: funding.token, amount: stake_amount });
    }

    // *SECURITY*  -  Stake must reflect the total committed value across BOTH sides of a liquidity bond. Measuring
    //                only one side opens a dust attack: (amount0 = 1 wei, amount1 = 1e18) would yield zero stake while
    //                committing real value. By default we normalize amount1 into token0 units at the pool's current
    //                price (slot0). If the user signals token1 as the preferred stake token, we normalize amount0 into
    //                token1 instead. Any other preference is ignored and falls back to token0.
    //                Caveat: on very thin pools an attacker can shift slot0 cheaply, so the per-bond stake reflects
    //                a manipulated price. This is bounded by SafeSwap's own 1% swap stake on the manipulation swap.
    function calculate_normalized_liquidity_stake(
        uint160 sqrtPriceX96,
        IERC20 token0,
        IERC20 token1,
        uint256 amount0,
        uint256 amount1,
        IERC20 preferred_stake_token
    )
    internal pure returns ( TokenAmount memory )
    {
        bool is_token1_preferred  =  address(preferred_stake_token) == address(token1);
        IERC20 stake_token        =  is_token1_preferred  ?  token1  :  token0;
        uint256 normalized_total  =  is_token1_preferred
            ?  amount1 + _convert_token0_to_token1_units( sqrtPriceX96, amount0 )
            :  amount0 + _convert_token1_to_token0_units( sqrtPriceX96, amount1 );

        uint256 stake_amount  =  normalized_total * LIQUIDITY_STAKE_PERCENTAGE / 100;

        // *SECURITY*  -  Bump dust to 1 wei. For 0-decimal / low-decimal tokens where 1 wei = 1 unit = real value
        //                (gaming ERC20s, fractional RWAs), this turns a free speculative bond into a meaningful stake.
        if(  stake_amount == 0  )  stake_amount  =  1;

        return TokenAmount({ token: stake_token, amount: stake_amount });
    }

    function _convert_token1_to_token0_units( uint160 sqrtPriceX96, uint256 amount1 ) private pure returns ( uint256 amount1_in_token0_units )
    {
        if(  amount1 == 0  )  return 0;

        // Price (token1 per token0)  =  sqrtPriceX96^2 / 2^192.
        // So amount1 in token0 units =  amount1 * 2^192 / sqrtPriceX96^2.
        // Performed as two mulDiv steps to avoid uint256 overflow on sqrtPriceX96^2 at high prices.
        uint256 intermediate      =  FullMath.mulDiv( amount1, FixedPoint96.Q96, sqrtPriceX96 );
        amount1_in_token0_units   =  FullMath.mulDiv( intermediate, FixedPoint96.Q96, sqrtPriceX96 );
    }

    function _convert_token0_to_token1_units( uint160 sqrtPriceX96, uint256 amount0 ) private pure returns ( uint256 amount0_in_token1_units )
    {
        if(  amount0 == 0  )  return 0;

        // Price (token1 per token0)  =  sqrtPriceX96^2 / 2^192.
        // So amount0 in token1 units =  amount0 * sqrtPriceX96^2 / 2^192.
        // Performed as two mulDiv steps to avoid uint256 overflow on sqrtPriceX96^2 at high prices.
        uint256 intermediate      =  FullMath.mulDiv( amount0, sqrtPriceX96, FixedPoint96.Q96 );
        amount0_in_token1_units   =  FullMath.mulDiv( intermediate, sqrtPriceX96, FixedPoint96.Q96 );
    }


    // ━━━━  PROTOCOL FEE CALCULATION  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    function calculate_protocol_fee( uint256 amount_out, uint24 pool_fee ) internal pure returns ( uint256 protocol_fee, uint256 user_amount )
    {
        uint256 effective_fee_rate  =  pool_fee < MIN_PROTOCOL_FEE_RATE  ?  MIN_PROTOCOL_FEE_RATE  :  pool_fee;
        protocol_fee                =  amount_out * effective_fee_rate / PROTOCOL_FEE_DIVISOR;
        user_amount                 =  amount_out - protocol_fee;
    }


    // ━━━━  REPRICING FEE  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    /**
     * @notice Compute the total swap fee (in Uniswap V4 pips) from a swap's estimated repricing surplus.
     * @param amount_in Input the swap pays (estimated at the base fee).
     * @param amount_out Output the swap receives (estimated at the base fee).
     * @param sqrt_price_after_x96 Estimated post-swap sqrt price — the terminal price the output is valued at.
     * @param zero_for_one Swap direction (token0 → token1 when true).
     * @param capture_percent LP capture share in percent (0..90): the share of SURPLUS paid to LPs.
     * @param base_fee_pips Base LP fee in v4 pips.
     * @return swap_fee_pips Base fee plus the repricing fee, in v4 pips, to be returned as the dynamic-fee override.
     *
     * @dev `surplus = (output valued at the post-swap price) − input`, in input-token units (clamped at 0). The repricing
     *      fee is `capture% × surplus`, expressed as a flat rate over the input: `capture% × surplus / amount_in × 1e6`.
     *      Direction-neutral. If enforcing the configured capture would require a 100%+ V4 fee, the swap reverts instead of
     *      silently under-capturing LPs. This is NOT `capture% × displacement`: that over-captures by ~2×.
     */
    function compute_repricing_fee_pips(
        uint256 amount_in,
        uint256 amount_out,
        uint160 sqrt_price_after_x96,
        bool zero_for_one,
        uint8 capture_percent,
        uint24 base_fee_pips
    ) internal pure returns ( uint24 swap_fee_pips )
    {
        uint256 repricing_pips  =  _repricing_fee_pips( amount_in, amount_out, sqrt_price_after_x96, zero_for_one, capture_percent );
        uint256 total_pips  =  uint256(base_fee_pips) + repricing_pips;

        if(  total_pips >= LPFeeLibrary.MAX_LP_FEE  )
        {
            revert RepricingFeeExceedsV4Limit({ total_fee_pips: total_pips, maximum_fee_pips: LPFeeLibrary.MAX_LP_FEE - 1 });
        }

        swap_fee_pips  =  uint24(total_pips);
    }

    /**
     * @notice Split the Uniswap V4 swap-amount convention into `(amount_in, amount_out)` given the simulator's counterpart.
     * @dev `amount_specified < 0` is exact-input (amount_in = |specified|, amount_out = counterpart); `> 0` is exact-output.
     */
    function compute_swap_amounts( int256 amount_specified, uint256 counterpart ) internal pure returns ( uint256 amount_in, uint256 amount_out )
    {
        if(  amount_specified < 0  )
        {
            amount_in   =  uint256(-amount_specified);
            amount_out  =  counterpart;
        }
        else
        {
            amount_out  =  uint256(amount_specified);
            amount_in   =  counterpart;
        }
    }

    // Repricing fee in v4 pips = `capture% × surplus / amount_in × 1e6`, where surplus = output valued at the post-swap price
    // minus the input, in input-token units (0 if not positive). FullMath keeps the valuation and pip conversion exact.
    function _repricing_fee_pips( uint256 amount_in, uint256 amount_out, uint160 sqrt_price_after_x96, bool zero_for_one, uint8 capture_percent )
    private pure returns ( uint256 )
    {
        if(  amount_in == 0  ||  capture_percent == 0  )  return 0;

        uint256 output_in_input_units  =  _value_output_in_input( amount_out, sqrt_price_after_x96, zero_for_one );
        if(  output_in_input_units <= amount_in  )  return 0;

        uint256 surplus  =  output_in_input_units - amount_in;

        // capture% × surplus / amount_in × 1e6  =  surplus × (capture% × 1e6/100) / amount_in.
        return FullMath.mulDiv( surplus, uint256(capture_percent) * PIPS_PER_PERCENT, amount_in );
    }

    // Value `amount_out` (the output token) in input-token units at the post-swap price P = (sqrtP / 2^96)^2 (token1/token0):
    //   zeroForOne (out = token1): value in token0 = amount_out / P = amount_out · 2^192 / sqrtP^2
    //   oneForZero (out = token0): value in token1 = amount_out · P = amount_out · sqrtP^2 / 2^192
    function _value_output_in_input( uint256 amount_out, uint160 sqrt_price_after_x96, bool zero_for_one )
    private pure returns ( uint256 )
    {
        uint256 sqrt_price  =  uint256(sqrt_price_after_x96);

        if(  zero_for_one  )
        {
            uint256 term  =  FullMath.mulDiv( amount_out, FixedPoint96.Q96, sqrt_price );
            return          FullMath.mulDiv( term, FixedPoint96.Q96, sqrt_price );
        }

        uint256 scaled  =  FullMath.mulDiv( amount_out, sqrt_price, FixedPoint96.Q96 );
        return              FullMath.mulDiv( scaled, sqrt_price, FixedPoint96.Q96 );
    }


    // ━━━━  SETTLEMENT  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    // *NATIVE*  -  V4 PoolManager has no receive(); native ETH cannot be transferred to it separately and then settled.
    //              It must arrive bundled with `settle{value:}()`. So for native we pull ETH to the router (which has
    //              receive()) and forward via msg.value on settle. For ERC20 we keep the direct user→PM path.
    function settle_input( IPoolManager pool_manager, BondContext memory context, IERC20 token, uint256 amount ) internal
    {
        if(  amount == 0  )  return;

        pool_manager.sync( Currency.wrap( address(token) ) );

        if(  address(token) == address(0)  )
        {
            context.pull( token, amount );
            pool_manager.settle{ value: amount }( );
        }
        else
        {
            context.send( token, amount, address(pool_manager) );
            pool_manager.settle( );
        }
    }

    /**
     * @notice Settle the swap input, send the user their net output, and take the protocol fee.
     * @param fee_recipient SafeSwap router address that receives the protocol fee (held for the treasury).
     */
    function settle_and_take(
        IPoolManager pool_manager,
        BondContext memory context,
        IERC20 token_in,
        IERC20 token_out,
        uint256 amount_in,
        uint256 user_output,
        uint256 protocol_fee,
        address fee_recipient
    ) internal
    {
        Currency currency_out  =  Currency.wrap( address(token_out) );

        settle_input( pool_manager, context, token_in, amount_in );

        pool_manager.take( currency_out, context.user, user_output );
        pool_manager.take( currency_out, fee_recipient, protocol_fee );
    }
}

contracts/Common/SigningLib.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "@BondRouteProtected/BondRouteProtected.sol";
import "@SafeSwapCommon/Types.sol";
import { StringHelperLib } from "@SafeSwapCommon/StringHelperLib.sol";
import { PriceLib } from "@SafeSwapCommon/PriceLib.sol";
import { EfficientHashLib } from "@Solady/utils/EfficientHashLib.sol";
import { LibString } from "@Solady/utils/LibString.sol";
import { SqrtPriceMath } from "@UniswapV4Core/libraries/SqrtPriceMath.sol";


/**
 * @title SigningLib
 * @notice Builds the SafeSwap BondRoute signing receipt in the locked `SIGNING_UX_REFERENCE_2.md` layout: terse symbolic
 *         display values (`= 1.25 WETH`, `<= 1.25 WETH + 4,200 USDC`, `2,850 ~ 3,150 USDC/WETH`, `|`-separated pool line),
 *         role-named single-word EIP-712 fields, each token symbol once per role, amounts at `FULL_PRECISION`, and the
 *         critical token addresses kept as raw typed anchors whose field name is the (sanitized) symbol.
 *
 * @dev Every display value is hashed as `keccak256(bytes(value))` inside the action struct, so the signed string is a
 *      canonical commitment. The token symbol is read defensively and sanitized (it lands inside the on-chain-generated
 *      EIP-712 type string, where an unsanitized `symbol()` could corrupt the type), reusing the NFT descriptor sanitizer.
 *      Token amounts are rendered at `StringHelperLib.FULL_PRECISION` — never the cosmetic card cap.
 */
library SigningLib {

    // ━━━━  ENVELOPE / FIXED TEXT  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    // BondRoute requires the typed string to start with this exact envelope and to contain the TokenAmount definition.
    string internal constant ENVELOPE_HEAD              =  "ExecuteBondAs(TokenAmount[] fundings,TokenAmount stake,uint256 salt,address protocol,";
    string internal constant TOKEN_AMOUNT_DEFINITION    =  "TokenAmount(address token,uint256 amount)";
    uint256 internal constant ENVELOPE_HEAD_LENGTH      =  85;

    // The only prose field — a nudge, not the control. The real check is `protocol` + token addresses against ChainConfig.
    string internal constant WARNING_VALUE          =  ">>  Check protocol and token addresses  <<";
    bytes32 internal constant WARNING_VALUE_HASH    =  keccak256( bytes(WARNING_VALUE) );

    // Every token amount carries an operator: `=` exact, `<=` cap (max), `>=` floor (min). Trailing space joins the amount.
    string internal constant OPERATOR_EXACT     =  "= ";
    string internal constant OPERATOR_AT_MOST   =  "<= ";
    string internal constant OPERATOR_AT_LEAST  =  ">= ";


    // ━━━━  DISPLAY VALUES  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    // "= 1.25 WETH"
    function render_single_amount_value( string memory operator, uint256 amount, uint8 decimals, string memory symbol )
    internal pure returns ( string memory )
    {
        return string.concat( operator, StringHelperLib.format_symbol_amount( amount, decimals, StringHelperLib.FULL_PRECISION, symbol ) );
    }

    // "<= 1.25 WETH + 4,200 USDC" — token1 first, token0 second (the locked receipt orientation).
    function render_pair_amount_value(
        string memory operator,
        uint256 amount1, uint8 decimals1, string memory symbol1,
        uint256 amount0, uint8 decimals0, string memory symbol0
    ) internal pure returns ( string memory )
    {
        return string.concat(
            operator,
            StringHelperLib.format_symbol_amount( amount1, decimals1, StringHelperLib.FULL_PRECISION, symbol1 ),
            " + ",
            StringHelperLib.format_symbol_amount( amount0, decimals0, StringHelperLib.FULL_PRECISION, symbol0 )
        );
    }

    // "0.3% base fee | 50% rebate | tick spacing 60"
    function render_pool_value( PoolInfo memory pool_info ) internal pure returns ( string memory )
    {
        return string.concat(
            StringHelperLib.format_bps_as_percent( pool_info.base_fee_bps ), "% base fee | ",
            LibString.toString( uint256(pool_info.rebate_percent) ), "% rebate | tick spacing ",
            LibString.toString( int256(pool_info.tick_spacing) )
        );
    }

    // "LP #9166523579416187058"
    function render_position_value( uint256 token_id ) internal pure returns ( string memory )
    {
        return string.concat( "LP #", LibString.toString( token_id ) );
    }

    // "600000000000000000 liquidity"
    function render_burn_value( uint128 liquidity ) internal pure returns ( string memory )
    {
        return string.concat( LibString.toString( uint256(liquidity) ), " liquidity" );
    }

    // "2,850 ~ 3,150 USDC/WETH" — the two bound prices as token0-per-token1, rendered low-to-high.
    function render_range_value(
        uint160 sqrt_price_a_x96, uint160 sqrt_price_b_x96,
        uint8 decimals0, uint8 decimals1, string memory symbol0, string memory symbol1
    ) internal pure returns ( string memory )
    {
        uint256 price_a  =  PriceLib.price0_per_1_scaled( sqrt_price_a_x96, decimals0, decimals1 );
        uint256 price_b  =  PriceLib.price0_per_1_scaled( sqrt_price_b_x96, decimals0, decimals1 );

        ( uint256 low, uint256 high )  =  price_a <= price_b  ?  ( price_a, price_b )  :  ( price_b, price_a );

        return string.concat(
            StringHelperLib.format_price_full( low ), " ~ ", StringHelperLib.format_price_full( high ), " ", symbol0, "/", symbol1
        );
    }

    // "3,002.5 USDC/WETH" — the init price as token0-per-token1.
    function render_price_value(
        uint160 sqrt_price_x96, uint8 decimals0, uint8 decimals1, string memory symbol0, string memory symbol1
    ) internal pure returns ( string memory )
    {
        return string.concat(
            StringHelperLib.format_price_full( PriceLib.price0_per_1_scaled( sqrt_price_x96, decimals0, decimals1 ) ),
            " ", symbol0, "/", symbol1
        );
    }


    // ━━━━  LIQUIDITY → DEPOSIT AMOUNTS  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    /**
     * @notice The token0 / token1 amounts a position of `liquidity` over `[sqrt_price_a_x96, sqrt_price_b_x96]` requires at the
     *         given price. Used to render the `Deposit` line from the committed liquidity and range (no separate funding field
     *         is signed — the deposit is fully determined by liquidity + range + price). Pure V4 math (`SqrtPriceMath`).
     */
    function calculate_amounts_for_liquidity( uint160 sqrt_price_x96, uint160 sqrt_price_a_x96, uint160 sqrt_price_b_x96, uint128 liquidity )
    internal pure returns ( uint256 amount0, uint256 amount1 )
    {
        if(  sqrt_price_a_x96 > sqrt_price_b_x96  )  ( sqrt_price_a_x96, sqrt_price_b_x96 )  =  ( sqrt_price_b_x96, sqrt_price_a_x96 );

        if(  sqrt_price_x96 <= sqrt_price_a_x96  )
        {
            amount0  =  SqrtPriceMath.getAmount0Delta( sqrt_price_a_x96, sqrt_price_b_x96, liquidity, false );
        }
        else if(  sqrt_price_x96 < sqrt_price_b_x96  )
        {
            amount0  =  SqrtPriceMath.getAmount0Delta( sqrt_price_x96, sqrt_price_b_x96, liquidity, false );
            amount1  =  SqrtPriceMath.getAmount1Delta( sqrt_price_a_x96, sqrt_price_x96, liquidity, false );
        }
        else
        {
            amount1  =  SqrtPriceMath.getAmount1Delta( sqrt_price_a_x96, sqrt_price_b_x96, liquidity, false );
        }
    }


    // ━━━━  TYPE STRING ASSEMBLY  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    /**
     * @notice Assemble the full EIP-712 `typed_string` and the `token_amount_offset` BondRoute validates.
     * @param field_declaration The action field inside the envelope, e.g. `"ExactInputSwap sS__SWAP__Ss"`.
     * @param inner_definition The action struct definition, e.g. `"ExactInputSwap(string Pay,...,address USDC)"`.
     * @dev The closing `)` of the envelope field sits between `field_declaration` and `inner_definition`; `inner_definition`
     *      itself ends with `)`, so the byte right before `TokenAmount(` is the required `)` BondRoute checks at offset - 1.
     */
    function build_typed_string( string memory field_declaration, string memory inner_definition )
    internal pure returns ( string memory typed_string, uint256 token_amount_offset )
    {
        token_amount_offset  =  ENVELOPE_HEAD_LENGTH + bytes(field_declaration).length + 1 + bytes(inner_definition).length;
        typed_string         =  string.concat( ENVELOPE_HEAD, field_declaration, ")", inner_definition, TOKEN_AMOUNT_DEFINITION );
    }

    function hash_string( string memory value ) internal pure returns ( bytes32 value_hash )
    {
        return EfficientHashLib.hash( bytes(value) );
    }

    function encode_address_word( address value ) internal pure returns ( bytes32 )
    {
        return bytes32( uint256( uint160( value ) ) );
    }

    function hash_words( bytes32 v0, bytes32 v1, bytes32 v2, bytes32 v3, bytes32 v4, bytes32 v5 )
    internal pure returns ( bytes32 )
    {
        return EfficientHashLib.hash( v0, v1, v2, v3, v4, v5 );
    }

    function hash_words( bytes32 v0, bytes32 v1, bytes32 v2, bytes32 v3, bytes32 v4, bytes32 v5, bytes32 v6 )
    internal pure returns ( bytes32 )
    {
        return EfficientHashLib.hash( v0, v1, v2, v3, v4, v5, v6 );
    }

    function hash_words( bytes32 v0, bytes32 v1, bytes32 v2, bytes32 v3, bytes32 v4, bytes32 v5, bytes32 v6, bytes32 v7 )
    internal pure returns ( bytes32 )
    {
        return EfficientHashLib.hash( v0, v1, v2, v3, v4, v5, v6, v7 );
    }

    function hash_words( bytes32 v0, bytes32 v1, bytes32 v2, bytes32 v3, bytes32 v4, bytes32 v5, bytes32 v6, bytes32 v7, bytes32 v8 )
    internal pure returns ( bytes32 )
    {
        return EfficientHashLib.hash( v0, v1, v2, v3, v4, v5, v6, v7, v8 );
    }

    function hash_words( bytes32 v0, bytes32 v1, bytes32 v2, bytes32 v3, bytes32 v4, bytes32 v5, bytes32 v6, bytes32 v7, bytes32 v8, bytes32 v9 )
    internal pure returns ( bytes32 )
    {
        return EfficientHashLib.hash( v0, v1, v2, v3, v4, v5, v6, v7, v8, v9 );
    }
}

contracts/Common/StringHelperLib.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import { IERC20 } from "@BondRouteProtected/BondRouteProtected.sol";
import { IERC20Metadata } from "@OpenZeppelin/token/ERC20/extensions/IERC20Metadata.sol";
import { DateTimeLib } from "@Solady/utils/DateTimeLib.sol";
import { LibString } from "@Solady/utils/LibString.sol";
import { ChainConfig } from "@ChainConfig/IChainConfig.sol";
import { CONFIG_SIGNER, NATIVE_TOKEN_SYMBOL_KEY, NATIVE_TOKEN_DECIMALS_KEY } from "@SafeSwapCommon/Definitions.sol";


/**
 * @title StringHelperLib
 * @notice String formatting and sanitization helpers for SafeSwap NFT metadata rendering.
 */
library StringHelperLib {

    uint256 internal constant MAX_SYMBOL_LENGTH  =  12;

    /// @notice Pass as `max_decimals_to_render` to render every fractional digit the token carries — a lossless,
    ///         canonical rendering in which distinct raw amounts always map to distinct strings. Use this
    ///         for signed display strings (canonical commitments); use a small cap only for cosmetic display.
    /// @dev    Resolves to `token_decimals` via the `>= token_decimals` clamp in `format_token_amount`.
    uint8 internal constant FULL_PRECISION  =  type(uint8).max;

    function attribute( string memory trait, string memory value ) internal pure returns ( string memory )
    {
        return string.concat( '{"trait_type":"', trait, '","value":"', value, '"}' );
    }

    function format_bps_as_percent( uint16 base_fee_bps ) internal pure returns ( string memory )
    {
        uint256 whole       =  uint256(base_fee_bps) / 100;
        uint256 fractional  =  uint256(base_fee_bps) % 100;

        if(  fractional == 0  )  return LibString.toString( whole );

        return string.concat( LibString.toString( whole ), ".", trimmed_fraction( fractional, 2 ) );
    }

    function format_bps_as_percent_string( uint256 value_bps ) internal pure returns ( string memory )
    {
        uint256 whole       =  value_bps / 100;
        uint256 fractional  =  value_bps % 100;

        if(  fractional == 0  )  return string.concat( LibString.toString( whole ), "%" );

        return string.concat( LibString.toString( whole ), ".", trimmed_fraction( fractional, 2 ), "%" );
    }

    function format_age( uint40 opened_at ) internal view returns ( string memory )
    {
        uint256 age_days  =  ( block.timestamp - opened_at ) / 1 days;
        return string.concat( LibString.toString( age_days ), "d" );
    }

    function format_symbol_amount( uint256 token_amount, uint8 decimals, uint8 max_decimals_to_render, string memory symbol ) internal pure returns ( string memory )
    {
        return string.concat( format_token_amount( token_amount, decimals, max_decimals_to_render ), " ", symbol );
    }

    /// @param max_decimals_to_render  Maximum fractional digits to render; 0 renders the integer part only. A
    ///                      small cap (e.g. 4) keeps cosmetic displays readable but is LOSSY — distinct amounts can
    ///                      collapse to the same string, so it must never anchor a signed commitment. Pass
    ///                      `FULL_PRECISION` for a lossless rendering.
    function format_token_amount( uint256 token_amount, uint8 decimals, uint8 max_decimals_to_render ) internal pure returns ( string memory )
    {
        if(  token_amount == 0  )  return "0";

        if(  decimals == 0  )  return LibString.toString( token_amount );

        // No real token reports 78+ decimals (10^78 overflows uint256). Invariant, not a real-usage failure, so
        // assert keeps it out of the ABI (see CODING_STYLE.md).
        assert(  decimals <= 77  );

        uint256 scale       =  pow10( decimals );
        uint256 whole       =  token_amount / scale;
        uint256 remainder   =  token_amount % scale;
        uint8 display       =  max_decimals_to_render >= decimals  ?  decimals  :  max_decimals_to_render;
        uint256 divisor     =  pow10( decimals - display );
        uint256 fractional  =  remainder / divisor;

        if(  fractional == 0  )
        {
            if(  whole == 0  &&  display == 0  )  return "<1";
            if(  whole == 0  )  return string.concat( "<0.", fractional_floor( display ) );
            return group_thousands( LibString.toString( whole ) );
        }

        return string.concat( group_thousands( LibString.toString( whole ) ), ".", format_fractional( fractional, display ) );
    }

    // Render a token1-per-token0 price scaled by 1e18 (see PriceLib) as a human decimal string:
    //   >= 1000        -> integer with thousands separators ("3,002")
    //   1 .. 1000      -> up to 2 decimals ("1.5")
    //   0.001 .. 1     -> up to 4 decimals ("0.05")
    //   < 0.001        -> ~3 significant figures, plain decimal, no exponent ("0.0000133")
    function format_price( uint256 scaled ) internal pure returns ( string memory )
    {
        if(  scaled == 0  )  return "0";

        uint256 whole  =  scaled / 1e18;

        if(  whole >= 1000  )  return group_thousands( LibString.toString( whole ) );

        if(  whole >= 1  )
        {
            uint256 frac_digits  =  ( scaled % 1e18 ) / 1e16;    // first 2 decimals
            if(  frac_digits == 0  )  return LibString.toString( whole );
            return string.concat( LibString.toString( whole ), ".", trimmed_fraction( frac_digits, 2 ) );
        }

        if(  scaled >= 1e15 )    // >= 0.001
        {
            uint256 frac_digits  =  scaled / 1e14;               // first 4 decimals
            return string.concat( "0.", trimmed_fraction( frac_digits, 4 ) );
        }

        // sub-0.001: count leading zeros, then keep ~3 significant figures.
        uint256 lead  =  0;
        uint256 v     =  scaled;
        while(  v < 1e17  )  {  v = v * 10;  lead = lead + 1;  }

        uint256 places  =  lead + 3;
        if(  places > 18  )  places = 18;

        uint256 sig  =  scaled / ( 10 ** ( 18 - places ) );
        if(  sig == 0  )  return "0";

        return string.concat( "0.", trimmed_fraction( sig, places ) );
    }

    // Render a token1-per-token0 (or token0-per-token1) price scaled by 1e18 for the SIGNED Create receipt. Unlike the
    // cosmetic `format_price` (which drops the fraction entirely once the whole part reaches 1,000 to keep the card tidy),
    // this keeps up to 4 trailing-zero-trimmed fractional digits at every magnitude, so "3,002.5 USDC/WETH" survives.
    // Sub-1 prices reuse `format_price`'s significant-figure tiers (already lossless enough at that magnitude).
    function format_price_full( uint256 scaled ) internal pure returns ( string memory )
    {
        if(  scaled == 0  )  return "0";

        uint256 whole  =  scaled / 1e18;
        if(  whole == 0  )  return format_price( scaled );

        uint256 frac_digits  =  ( scaled % 1e18 ) / 1e14;    // first 4 decimals
        if(  frac_digits == 0  )  return group_thousands( LibString.toString( whole ) );

        return string.concat( group_thousands( LibString.toString( whole ) ), ".", trimmed_fraction( frac_digits, 4 ) );
    }

    // Zero-pad `value` to `width` digits, then drop trailing zeros (e.g. value=500,width=4 -> "05").
    function trimmed_fraction( uint256 value, uint256 width ) internal pure returns ( string memory )
    {
        bytes memory buffer  =  new bytes( width );

        for(  uint256 i = width  ;  i > 0  ;  i = i - 1  )
        {
            buffer[ i - 1 ]  =  bytes1( uint8( 48 + ( value % 10 ) ) );
            value            =  value / 10;
        }

        uint256 length  =  width;
        while(  length > 0  &&  buffer[ length - 1 ] == 0x30  )
        {
            length  =  length - 1;
        }

        assembly { mstore( buffer, length ) }

        return string(buffer);
    }

    // Render a Unix timestamp (seconds, UTC) as "YYYY-MM-DD HH:MM UTC". Used as the snapshot "as of" stamp so a
    // marketplace-cached card visibly carries the time its live data was rendered.
    function format_utc_datetime( uint256 timestamp ) internal pure returns ( string memory )
    {
        ( uint256 year, uint256 month, uint256 day, uint256 hour, uint256 minute, )  =  DateTimeLib.timestampToDateTime( timestamp );

        return string.concat(
            LibString.toString( year ), "-", two_digits( month ), "-", two_digits( day ),
            " ", two_digits( hour ), ":", two_digits( minute ), " UTC"
        );
    }

    function two_digits( uint256 value ) internal pure returns ( string memory )
    {
        return value < 10  ?  string.concat( "0", LibString.toString( value ) )  :  LibString.toString( value );
    }

    // Insert thousands separators into a non-negative integer string: "1234567" -> "1,234,567".
    function group_thousands( string memory input ) internal pure returns ( string memory )
    {
        bytes memory raw  =  bytes(input);
        uint256 len       =  raw.length;
        if(  len <= 3  )  return input;

        uint256 commas    =  ( len - 1 ) / 3;
        bytes memory out  =  new bytes( len + commas );
        uint256 oi        =  out.length;
        uint256 count     =  0;

        for(  uint256 i = len  ;  i > 0  ;  i = i - 1  )
        {
            oi          =  oi - 1;
            out[ oi ]   =  raw[ i - 1 ];
            count       =  count + 1;

            if(  count % 3 == 0  &&  i > 1  )
            {
                oi         =  oi - 1;
                out[ oi ]  =  ",";
            }
        }

        return string(out);
    }

    function format_fractional( uint256 fractional, uint8 width ) internal pure returns ( string memory )
    {
        bytes memory buffer  =  new bytes( width );

        for(  uint256 i = width  ;  i > 0  ;  i = i - 1  )
        {
            buffer[ i - 1 ]  =  bytes1( uint8( 48 + ( fractional % 10 ) ) );
            fractional       =  fractional / 10;
        }

        uint256 length  =  width;
        while(  length > 0  &&  buffer[ length - 1 ] == 0x30  )
        {
            length  =  length - 1;
        }

        assembly { mstore( buffer, length ) }

        return string(buffer);
    }

    function fractional_floor( uint8 width ) internal pure returns ( string memory )
    {
        bytes memory buffer  =  new bytes( width );

        for(  uint256 i = 0  ;  i < width - 1  ;  i = i + 1  )
        {
            buffer[ i ]  =  0x30;
        }

        buffer[ width - 1 ]  =  0x31;

        return string(buffer);
    }

    function pow10( uint8 exponent ) internal pure returns ( uint256 value )
    {
        value  =  1;

        for(  uint256 i = 0  ;  i < exponent  ;  i = i + 1  )
        {
            value  =  value * 10;
        }
    }

    // Safe display symbol for embedding in JSON, SVG, and the signed receipt: the native token (`address(0)`) renders the
    // chain-configured native symbol; a non-conforming `symbol()` (missing, reverting, or non-string) falls back to the short
    // address; the result is filtered to an alphanumeric subset so it can never break out of the surrounding XML/JSON/type string.
    function get_sanitized_token_symbol( IERC20 token ) internal view returns ( string memory )
    {
        if(  address(token) == address(0)  )  return get_native_token_symbol( );

        try IERC20Metadata( address(token) ).symbol( ) returns ( string memory symbol )
        {
            return sanitize( symbol );
        }
        catch
        {
            return sanitize( LibString.toHexString( address(token) ) );
        }
    }

    // The native token (`address(0)`) renders the chain-configured native decimals; a token whose `decimals()` is missing or
    // reverts falls back to the universal 18-decimal ERC20 default.
    function get_token_decimals( IERC20 token ) internal view returns ( uint8 )
    {
        if(  address(token) == address(0)  )  return get_native_token_decimals( );

        try IERC20Metadata( address(token) ).decimals( ) returns ( uint8 decimals )
        {
            return decimals;
        }
        catch
        {
            return 18;
        }
    }

    // The native token (`address(0)`) display name and decimals are chain-scoped, read live from ChainConfig so a chain rename
    // (e.g. ETH -> ETC) is reflected by republishing the key with no redeploy. These are the source of truth the signing
    // receipt and the NFT card both render; an unset key reverts `KeyNotSet`, and the size-bound descriptors touch-read both
    // in their constructors so a misconfigured deploy fails fast rather than at first render. Sanitized like any other symbol.
    function get_native_token_symbol( ) internal view returns ( string memory )
    {
        return sanitize( LibString.fromSmallString( ChainConfig.read_bytes32( CONFIG_SIGNER, NATIVE_TOKEN_SYMBOL_KEY ) ) );
    }

    function get_native_token_decimals( ) internal view returns ( uint8 )
    {
        return uint8( ChainConfig.read_uint( CONFIG_SIGNER, NATIVE_TOKEN_DECIMALS_KEY ) );
    }

    // Deploy-time guard for the size-bound descriptors: require the native-token display keys before first render so a
    // misconfigured deploy fails fast rather than at the first signing receipt or card. An unset key reverts `KeyNotSet`.
    function validate_native_token_config( ) internal view
    {
        if(  bytes( get_native_token_symbol() ).length == 0  )  revert( "SafeSwap: native_token_symbol not set" );
        if(  get_native_token_decimals() == 0  )                revert( "SafeSwap: native_token_decimals not set" );
    }

    // Keep only [0-9A-Za-z], '.', '-' and cap the length. Drops quotes, angle brackets, backslashes, and control bytes, so a
    // hostile token symbol cannot inject markup or JSON punctuation.
    function sanitize( string memory input ) internal pure returns ( string memory )
    {
        bytes memory raw    =  bytes(input);
        uint256 limit       =  raw.length < MAX_SYMBOL_LENGTH  ?  raw.length  :  MAX_SYMBOL_LENGTH;
        bytes memory clean  =  new bytes( limit );
        uint256 count       =  0;

        for(  uint256 i = 0  ;  i < limit  ;  i = i + 1  )
        {
            bytes1 c  =  raw[ i ];

            bool is_allowed  =  ( c >= 0x30 && c <= 0x39 )       // 0-9
                                ||  ( c >= 0x41 && c <= 0x5A )   // A-Z
                                ||  ( c >= 0x61 && c <= 0x7A )   // a-z
                                ||  c == 0x2E                    // .
                                ||  c == 0x2D;                   // -

            if(  is_allowed  )
            {
                clean[ count ]  =  c;
                count           =  count + 1;
            }
        }

        if(  count == 0  )  return "TOKEN";

        assembly { mstore( clean, count ) }    // Truncate to the kept bytes.

        return string(clean);
    }
}

contracts/Common/Types.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import { IERC20 } from "@BondRouteProtected/BondRouteProtected.sol";


// ━━━━  DATA STRUCTURES  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

/**
 * @notice SafeSwap pool configuration shared by all SafeSwap actions.
 * @param base_fee_bps Base LP fee in basis points (1 bps = 0.01%), 0..999. Selects the config hook (encoded in its address).
 * @param rebate_percent LP capture share in percent (0..90, in 10% steps). Selects the config hook and the repricing fee share.
 * @param tick_spacing Pool tick spacing.
 */
struct PoolInfo {
    uint16 base_fee_bps;
    uint8 rebate_percent;
    int24 tick_spacing;
}

/**
 * @notice Immutable metadata for a SafeSwap NFT-backed Uniswap V4 position.
 * @param opened_at Timestamp when the LP NFT was minted.
 * @param hook SafeSwap config hook (clone) that identifies the pool's base fee and capture share.
 * @param token0 Pool currency0.
 * @param token1 Pool currency1.
 * @param base_fee_bps Base LP fee in basis points. Derivable from `hook`, stored for cheap rendering and verification.
 * @param rebate_percent LP capture share in percent. Derivable from `hook`, stored for cheap rendering and verification.
 * @param tick_spacing Pool tick spacing.
 * @param tick_lower Lower tick of the position.
 * @param tick_upper Upper tick of the position.
 */
struct SafeSwapPositionInfo {
    uint40 opened_at;
    address hook;
    IERC20 token0;
    IERC20 token1;
    uint16 base_fee_bps;
    uint8 rebate_percent;
    int24 tick_spacing;
    int24 tick_lower;
    int24 tick_upper;
}

